nign."}, {"key": "d28", "type": "advice", "problem": "How to make a replication of emergent misalignment results comparable to the original findings.", "did": "He asks for exactly the same evaluation as in the original paper so results can be compared directly.", "alternatives_named": ["a different, ad hoc evaluation"], "stated_reason": "Direct comparison requires the same evaluation."}, {"key": "d29", "type": "advice", "problem": "How broadly to measure misalignment when claiming a finetuning effect.", "did": "He points out that there are many possible misalignment evals and that the original paper used a number of very different ones, implying results should be checked across several evals.", "alternatives_named": ["relying on a single misalignment eval"], "stated_reason": "There are many possible evals for misalignment."}, {"key": "d30", "type": "disagreement", "problem": "Whether the default outcome without truthfulness-focused intervention is no regulation of AI truthfulness.", "did": "He argues that some form of regulation is a plausible default, rather than accepting that none will occur.", "alternatives_named": ["governments and tech platforms do not regulate whether AI needs to be truthful"], "stated_reason": "If novel AI-driven deception happens repeatedly, he expects voluntary or government regulation, especially where existing laws on human deception are hard to apply."}]}
